  features {}
}

resource "azurerm_resource_group" "hub_rg" {
  name     = "rg-hub-prod"
  location = "East US"
}

# 1. Virtual Network
resource "azurerm_virtual_network" "hub_vnet" {
  name                = "vnet-hub"
  address_space       = ["10.0.0.0/16"]
  location            = azurerm_resource_group.hub_rg.location
  resource_group_name = azurerm_resource_group.hub_rg.name
}

# 2. AzureFirewallSubnet (Required name for Azure Firewall)
resource "azurerm_subnet" "firewall_subnet" {
  name                 = "AzureFirewallSubnet"
  resource_group_name  = azurerm_resource_group.hub_rg.name
  virtual_network_name = azurerm_virtual_network.hub_vnet.name
  address_prefixes     = ["10.0.0.0/26"]
}

# 3. GatewaySubnet (Required name for VPN/ExpressRoute Gateway)
resource "azurerm_subnet" "gateway_subnet" {
  name                 = "GatewaySubnet"
  resource_group_name  = azurerm_resource_group.hub_rg.name
  virtual_network_name = azurerm_virtual_network.hub_vnet.name
  address_prefixes     = ["10.0.1.0/27"]
}

# 4. snet-mgmt Subnet
resource "azurerm_subnet" "mgmt_subnet" {
  name                 = "snet-mgmt"
  resource_group_name  = azurerm_resource_group.hub_rg.name
  virtual_network_name = azurerm_virtual_network.hub_vnet.name
  address_prefixes     = ["10.0.2.0/24"]
}

# 5. Network Security Group for snet-mgmt
resource "azurerm_network_security_group" "mgmt_nsg" {
  name                = "nsg-mgmt"
  location            = azurerm_resource_group.hub_rg.location
  resource_group_name = azurerm_resource_group.hub_rg.name

  security_rule {
    name                       = "AllowHTTPSInbound"
    priority                   = 100
    direction                  = "Inbound"
    access                     = "Allow"
    protocol                   = "Tcp"
    source_port_range          = "*"
    destination_port_range     = "443"
    source_address_prefix      = "*"
    destination_address_prefix = "*"
  }

  # Implicitly denies all other inbound traffic via default rules, 
  # but we can add an explicit deny for clarity if desired.
}

# 6. Subnet-NSG Association
resource "azurerm_subnet_network_security_group_association" "mgmt_assoc" {
  subnet_id                 = azurerm_subnet.mgmt_subnet.id
  network_security_group_id = azurerm_network_security_group.mgmt_nsg.id
}

# Outputs
output "vnet_id" {
  value = azurerm_virtual_network.hub_vnet.id
}

